/**
 * Writes the MCP tools' generated files from `src/http/mcp/tools/*.ts` (#5924):
 *
 * - `src/http/mcp/tools/index.ts`: one sorted line per tool file, so a pull
 *   that adds a tool adds one line and never edits another pull's.
 * - the `## Tools` table in `docs/MCP.md`, between its `tools:begin` and
 *   `tools:end` markers, from each tool's `doc` and `writes`.
 *
 *   bun scripts/mcp-tools.ts          write both
 *   bun scripts/mcp-tools.ts --check  exit 1, naming the file, when either is stale
 *
 * `test/mcp-tools.test.ts` runs the check, so a pull that adds a tool file
 * without running this goes red with the command to run.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { byName } from "../src/http/mcp/shared.ts";

const ROOT = join(import.meta.dir, "..");
const DIR = join(ROOT, "src/http/mcp/tools");
const INDEX = join(DIR, "index.ts");
const DOC = join(ROOT, "docs/MCP.md");
const BEGIN = "<!-- tools:begin: generated by `bun scripts/mcp-tools.ts` from each tool's `doc` -->";
const END = "<!-- tools:end -->";

/** The tool files, by name: every `<name>.ts` here but the index. */
export function toolFiles(dir = DIR): string[] {
  return readdirSync(dir)
    .filter((f) => /^[a-z][a-z0-9_]*\.ts$/.test(f) && f !== "index.ts")
    .map((f) => f.slice(0, -3))
    .sort();
}

export function indexText(names: readonly string[]): string {
  return [
    "// Generated by `bun scripts/mcp-tools.ts` from the files beside it; do not edit.",
    "// One line per tool, sorted: a new tool is a new file and one new line here.",
    ...names.map((n) => `export { tool as ${n} } from "./${n}.ts";`),
    "",
  ].join("\n");
}

type Documented = { readonly name: string; readonly doc?: string; readonly writes: boolean };

export function tableText(tools: readonly Documented[]): string {
  const rows = [...tools]
    .filter((t) => t.doc !== undefined)
    .sort(byName)
    .map((t) => `| \`${t.name}\` | ${t.doc} | ${t.writes ? "yes" : ""} |`);
  return [BEGIN, "", "| tool | does | writes |", "| ---- | ---- | ------ |", ...rows, "", END].join("\n");
}

/** docs/MCP.md with its table replaced by `table`. */
export function withTable(md: string, table: string): string {
  const from = md.indexOf(BEGIN);
  const to = md.indexOf(END);
  if (from < 0 || to < from) throw new Error(`docs/MCP.md has no ${BEGIN} … ${END} markers`);
  return md.slice(0, from) + table + md.slice(to + END.length);
}

if (import.meta.main) {
  const check = process.argv.includes("--check");
  const stale: string[] = [];
  const index = indexText(toolFiles());
  if (readFileSync(INDEX, "utf8") !== index) {
    stale.push("src/http/mcp/tools/index.ts");
    if (!check) writeFileSync(INDEX, index);
  }
  // After the index is current, so a new file's row is in the table.
  const { TOOLS } = await import("../src/http/mcp/tools.ts");
  const { REPORT_TOOL } = await import("../src/http/mcp.ts");
  const md = readFileSync(DOC, "utf8");
  const doc = withTable(md, tableText([...TOOLS, REPORT_TOOL]));
  if (md !== doc) {
    stale.push("docs/MCP.md");
    if (!check) writeFileSync(DOC, doc);
  }
  if (check && stale.length > 0) {
    console.error(`stale: ${stale.join(", ")}; run \`bun scripts/mcp-tools.ts\``);
    process.exit(1);
  }
  if (!check) console.log(stale.length > 0 ? `wrote ${stale.join(", ")}` : "current");
}
